/// Applies a boolean flag or collects a non-flag positional token.
void _applyBooleanOrPositional(String arg) {
  switch (arg) {
    case '--verbose':
      _verbose = true;
    case '--debug':
      _verbose = true;
      _debug = true;
    case '--quiet':
      _quiet = true;
    case '--toon':
      _outputFormat = 'toon';
    case '--mini':
      _outputFormat = 'mini';
    default:
      if (!arg.startsWith('--')) {
        _nonFlags.add(arg);
      }
  }
}

